function makeRing(radius, color, opacity) {
  const g = new THREE.RingGeometry(radius - 0.08, radius, 40),
    m = new THREE.MeshBasicMaterial({
      color,
      transparent: true,
      opacity,
      side: THREE.DoubleSide,
      depthWrite: false,
    }),
    mesh = new THREE.Mesh(g, m);
  mesh.rotation.x = -Math.PI / 2;
  mesh.position.y = 0.56;
  return mesh;
}

function box(w, h, d, color) {
  return new THREE.Mesh(
    new THREE.BoxGeometry(w, h, d),
    new THREE.MeshLambertMaterial({ color }),
  );
}

function vbox(w, h, d, color, px = 0, py = 0, pz = 0) {
  const m = box(w, h, d, color);
  m.position.set(px, py, pz);
  return m;
}

function addVoxelDetails(g, defs) {
  for (const d of defs) {
    const m = vbox(d[0], d[1], d[2], d[3], d[4], d[5], d[6]);
    g.add(m);
  }
}

// Dispose resources owned by a removed model; shared pickup assets are pooled separately.
function disposeObject(object) {
  if (!object) return;
  object.removeFromParent();
  const geometries = new Set(),
    materials = new Set();
  object.traverse((o) => {
    if (o.geometry) geometries.add(o.geometry);
    for (const m of Array.isArray(o.material) ? o.material : [o.material])
      if (m) materials.add(m);
  });
  geometries.forEach((g) => g.dispose());
  materials.forEach((m) => m.dispose());
}

function updateEnvironment(dt, t) {
  nightK += ((phase === "night" ? 1 : 0) - nightK) * Math.min(1, dt * 1.2);
  const sky = new THREE.Color(0xbcd8ee).lerp(new THREE.Color(0x0a1226), nightK);
  scene.background.copy(sky);
  scene.fog.color.copy(sky);
  sun.intensity = 1.15 - nightK * 0.95;
  hemi.intensity = 0.9 - nightK * 0.55;
  const sa = (phase === "day" ? 1 - phaseT / 30 : 0.5) * Math.PI;
  sun.position.set(Math.cos(sa) * 30, Math.max(6, Math.sin(sa) * 30), 10);
  const fr = fuel / 100;
  fireLight.intensity =
    (0.6 + fr * 2.2) * (1 + nightK * 0.8) + Math.sin(t * 11) * 0.25;
  fireLight.distance = 12 + fr * 12;
}


// ---- voxel-style ----
// Visual sub-voxels use the existing world instancing draw. Logical resource cells stay intact.
// Reserve one slot per remaining logical block; detail degrades safely if capacity is tight.
function resourceVisualParts(e) {
  const { x, y, z, b } = e,
    j = hashJitter(x, y, z);
  if (b.t === "wood")
    return [
      [0, 0, 0, 0.44, 1, 0.44, 0x92623e],
      [0.23, 0.13, 0, 0.06, 0.53, 0.36, 0xc08b56],
    ];
  if (b.t === "leaf")
    return [
      [-0.23, -0.03, -0.23, 0.48, 0.6 * j, 0.48, 0x416e76],
      [0.23, 0.04, -0.23, 0.48, 0.72 * j, 0.48, 0x4f8187],
      [-0.23, 0.08, 0.23, 0.48, 0.65 * j, 0.48, 0x568891],
      [0.23, -0.03, 0.23, 0.48, 0.55 * j, 0.48, 0x3e6971],
      [0, 0.4, 0, 0.86, 0.13, 0.84, 0xe4f2f6],
    ];
  if (b.t === "coal")
    return [
      [-0.21, -0.15, 0, 0.5, 0.68, 0.72, 0x354251],
      [0.22, -0.04, -0.13, 0.44, 0.85, 0.54, 0x52677c],
      [0.15, -0.17, 0.29, 0.5, 0.64, 0.28, 0x728b9e],
      [-0.2, 0.22, 0, 0.42, 0.1, 0.59, 0xd6e5ec],
    ];
  return null;
}


// ---- audio ----
// audio system — v12, integrated from the deployed v11.

function initAudio() {
  if (audioCtx) return;
  audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  masterGain = audioCtx.createGain();
  masterGain.gain.value = 0.22;
  masterGain.connect(audioCtx.destination);
}

function tone(freq = 440, dur = 0.08, type = "sine", vol = 0.13, slide = 1) {
  if (!audioCtx) return;
  const o = audioCtx.createOscillator(),
    g = audioCtx.createGain();
  o.type = type;
  o.frequency.setValueAtTime(freq, audioCtx.currentTime);
  o.frequency.exponentialRampToValueAtTime(
    Math.max(40, freq * slide),
    audioCtx.currentTime + dur,
  );
  g.gain.setValueAtTime(vol, audioCtx.currentTime);
  g.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + dur);
  o.connect(g);
  g.connect(masterGain);
  o.start();
  o.stop(audioCtx.currentTime + dur);
}

function sfx(name) {
  if (!audioCtx) return;
  const now = performance.now();
  if (lastSfx[name] && now - lastSfx[name] < 45) return;
  lastSfx[name] = now;
  if (name === "pickup") {
    if (lastSfx.pickupNote && now - lastSfx.pickupNote < 100) return;
    lastSfx.pickupNote = now;
    tone(880, 0.055, "sine", 0.04, 1.3);
  } else if (name === "deliver") {
    tone(420, 0.08, "triangle", 0.055, 0.7);
  } else if (name === "wood") {
    tone(170, 0.06, "square", 0.08, 1.8);
    tone(280, 0.08, "triangle", 0.06, 1.3);
  } else if (name === "coal") {
    tone(110, 0.09, "square", 0.09, 0.72);
    tone(190, 0.05, "triangle", 0.05, 0.8);
  } else if (name === "iron") {
    tone(520, 0.05, "triangle", 0.06, 1.3);
    tone(780, 0.09, "sine", 0.05, 1.1);
  } else if (name === "build") {
    tone(180, 0.09, "square", 0.08, 1.3);
    setTimeout(() => tone(330, 0.12, "triangle", 0.09, 1.45), 70);
  } else if (name === "upgrade") {
    tone(330, 0.08, "triangle", 0.08, 1.3);
    setTimeout(() => tone(520, 0.1, "triangle", 0.08, 1.25), 70);
    setTimeout(() => tone(780, 0.14, "sine", 0.07, 1.05), 145);
  } else if (name === "shoot") tone(760, 0.035, "square", 0.025, 0.72);
  else if (name === "flame") tone(125, 0.12, "sawtooth", 0.035, 0.55);
  else if (name === "kill") {
    const pitch = 1 + Math.min(8, Math.max(0, combo - 1)) * 0.065;
    tone(220 * pitch, 0.04, "square", 0.055, 1.8);
    tone(440 * pitch, 0.07, "triangle", 0.04, 1.25);
  } else if (name === "wave") {
    tone(105, 0.3, "sawtooth", 0.09, 0.65);
    setTimeout(() => tone(85, 0.35, "sawtooth", 0.08, 0.55), 160);
  } else if (name === "base" || name === "capture" || name === "rescue") {
    tone(392, 0.1, "triangle", 0.08, 1.2);
    setTimeout(() => tone(587, 0.12, "triangle", 0.08, 1.2), 90);
    setTimeout(() => tone(784, 0.18, "sine", 0.07, 1.05), 190);
  } else if (name === "boss") {
    tone(70, 0.45, "sawtooth", 0.12, 0.55);
    setTimeout(() => tone(55, 0.55, "square", 0.09, 0.5), 240);
  }
}


